-- Which objects the migrations in supabase/migrations define that the linked database lacks.
-- Migrations are applied by hand (supabase db query --linked -f), so a file can be missed or
-- half-applied; run this after a batch:  supabase db query --linked -f scripts/audit-schema.sql
-- Known false positive: categories.accent_color (0061 drops it on purpose).

select 'missing_function' as kind, x as name from unnest(array['admin_tenant_overview','ai_usage_add','busiest_hours','can_manage_menu','can_manage_register','can_manage_reservations','can_operate_pos','can_use_loyalty','can_use_whatsapp','can_view_sales','categories_block_parent_with_children','categories_check_parent','claim_due_reminders','claim_pending_invites','count_stock','flow_counter_add','guard_updated_at','handle_new_tenant','handle_new_user','is_member','is_super_admin','loyalty_summary','mark_options','media_referenced_paths','media_write_allowed','move_stock','next_invoice_folio','orders_deduct_stock','owns_tenant','prune_print_jobs','rate_limit_hit','request_reservation','resync_reservation_instants','sales_series','set_location_availability','set_option_availability','set_product_availability','set_reservation_starts_at','tabs_award_loyalty','tabs_deduct_stock','tenant_stats','top_customers','top_products']) x where not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=x)
union all select 'missing_table', x from unnest(array['ai_providers_config','ai_runs','ai_usage_counters','audit_log','branch_sold_out','branches','categories','device_push_tokens','employees','floor_combinations','floor_tables','ingredient_stock','ingredients','invoices','kitchen_tickets','loyalty_customers','loyalty_events','loyalty_program','orders','payment_accounts','payments','platform_settings','print_agents','print_jobs','printers','product_ingredients','product_views','products','profiles','promotions','purchase_orders','push_subscriptions','rate_limits','register_shifts','reservation_areas','reservation_notifications','reservations','separators','stock_movements','subscriptions','tab_items','tabs','tenant_cfdi','tenant_contact','tenant_invites','tenant_landing','tenant_members','tenant_ordering','tenant_theme','tenants','time_entries','whatsapp_canned_replies','whatsapp_contacts','whatsapp_conversations','whatsapp_credentials','whatsapp_events','whatsapp_faqs','whatsapp_flow_counters','whatsapp_flow_runs','whatsapp_flow_versions','whatsapp_flows','whatsapp_goals','whatsapp_messages','whatsapp_numbers','whatsapp_settings','whatsapp_templates']) x where not exists (select 1 from information_schema.tables where table_schema='public' and table_name=x)
union all select 'missing_column', t||'.'||c from (values ('branches','hours'),('branches','maps_url'),('categories','accent_color'),('categories','branch_id'),('categories','icon'),('categories','parent_id'),('categories','station'),('categories','theme'),('kitchen_tickets','employee_id'),('orders','accepted_at'),('orders','branch_id'),('orders','customer_phone'),('orders','discount'),('orders','edited_at'),('orders','invoice_id'),('orders','payment_method'),('orders','payment_status'),('orders','refund_ref'),('orders','reject_reason'),('orders','status'),('orders','stock_deducted_at'),('payment_accounts','credentials'),('payments','employee_id'),('payments','kind'),('platform_settings','ai_default_model'),('platform_settings','ai_enabled'),('platform_settings','branch_amount_basic'),('platform_settings','extra_amount'),('platform_settings','payment_fee_percent'),('platform_settings','pos_addon_amount'),('platform_settings','pro_amount'),('products','compare_at_price'),('products','cost'),('products','is_hidden'),('products','option_groups'),('products','removables'),('products','sat_product_code'),('products','sku'),('purchase_orders','branch_id'),('register_shifts','register'),('reservations','table_ids'),('reservations','whatsapp_conversation_id'),('stock_movements','branch_id'),('subscriptions','addons'),('subscriptions','is_additional'),('subscriptions','plan'),('tabs','customer_phone'),('tabs','discount'),('tabs','employee_id'),('tabs','invoice_id'),('tabs','promo_discount'),('tabs','refunded'),('tabs','server_name'),('tabs','stock_deducted_at'),('tenant_contact','maps_url'),('tenant_contact','reservation_required'),('tenant_contact','reservation_shifts'),('tenant_contact','reservation_slot_minutes'),('tenant_contact','reservations_enabled'),('tenant_landing','landing_mode'),('tenant_ordering','cash_count_mode'),('tenant_ordering','collect_name'),('tenant_ordering','note_placeholder'),('tenant_ordering','order_alerts'),('tenant_ordering','ordering_enabled'),('tenant_ordering','ordering_qr_enabled'),('tenant_ordering','orders_board'),('tenant_ordering','payment_methods'),('tenant_ordering','pos_lock_after_sale'),('tenant_ordering','pos_tables'),('tenant_ordering','print_receipt_mode'),('tenant_theme','background_music_url'),('tenant_theme','button_color'),('tenant_theme','card_color'),('tenant_theme','cover_image_url'),('tenant_theme','custom_font_url'),('tenant_theme','font_category'),('tenant_theme','logo_wide_url'),('tenant_theme','menu_mode'),('tenant_theme','search_bg_color'),('tenant_theme','tab_bar_color'),('tenant_theme','tab_selected_color'),('tenants','country_iso'),('tenants','timezone'),('whatsapp_conversations','active_flow_run_id'),('whatsapp_conversations','transport'),('whatsapp_numbers','bridge_session_id')) v(t,c) where not exists (select 1 from information_schema.columns where table_schema='public' and table_name=v.t and column_name=v.c)
order by 1,2;
